    if (!memory_)
        return false;

    auto link = memory_->offset(link_to_position(link_) + Link::size);
    if (is_null(link))
        return false;

    BC_PUSH_WARNING(NO_UNSAFE_COPY_N)
    return std::equal(key_.begin(), key_.end(), link);
    BC_POP_WARNING()
}

